theorem isIntegrallyClosed_of_isAffineOpen {X : Scheme.{u}} [IsIntegral X] {W : X.Opens}
    (hW : IsAffineOpen W) [Nonempty W]
    (h : ∀ x ∈ W, IsIntegrallyClosed (X.presheaf.stalk x)) : IsIntegrallyClosed Γ(X, W)

theorem valuation_aeval_derivative_eq_one (hQ : ∀ q : ℚ, algebraMap ℚ K q ∈ O) {x : K}
    (hx : x ∈ O) {q : ℚ[X]} (hq : q.Separable) (hv : O.valuation (aeval x q) < 1) :
    O.valuation (aeval x (derivative q)) = 1

lemma smoothLocus_congr {Y Z : Scheme.{u}} {g h : Y ⟶ Z}
    [LocallyOfFinitePresentation g] [LocallyOfFinitePresentation h] (hgh : g = h) :
    g.smoothLocus = h.smoothLocus

theorem exists_span_X_sub_C_of_isPrime {k : Type*} [Field k] [IsAlgClosed k]
    {Q : Ideal (Polynomial k)} [Q.IsPrime] (hQ : Q ≠ ⊥) :
    ∃ a : k, Q = Ideal.span {Polynomial.X - Polynomial.C a}
